protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    List<V> vertexList = new ArrayList<>();
    if (edgeList.isEmpty()) {
        return new GraphPathImpl<>(graph, null, vertexList, 0.0);
    }
    V startVertex = graph.getEdgeSource(edgeList.get(0));
    vertexList.add(startVertex);
    V currentVertex = startVertex;
    while (!edgeList.isEmpty()) {
        for (E edge : edgeList) {
            if (graph.getEdgeSource(edge).equals(currentVertex)) {
                currentVertex = graph.getEdgeTarget(edge);
                vertexList.add(currentVertex);
                edgeList.remove(edge);
                break;
            } else if (graph.getEdgeTarget(edge).equals(currentVertex)) {
                currentVertex = graph.getEdgeSource(edge);
                vertexList.add(currentVertex);
                edgeList.remove(edge);
                break;
            }
        }
    }
    double weight = tour.stream().mapToDouble(graph::getEdgeWeight).sum();
    return new GraphPathImpl<>(graph, startVertex, vertexList, weight);
}

