public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    // Assuming ThreadSnapshot and ProfileAnalyzeTimeRange are defined elsewhere
    // and that the file contains serialized ThreadSnapshot objects
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        ThreadSnapshot snapshot;
        while ((snapshot = (ThreadSnapshot) ois.readObject()) != null) {
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (snapshot.getTimestamp() >= range.getStartTime() && snapshot.getTimestamp() <= range.getEndTime()) {
                    threadSnapshots.add(snapshot);
                    break;
                }
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IOException("Class not found while reading from file", e);
    }
    return threadSnapshots;
}
